            return int(s[2:], base)

        # Parse sign
        if s.startswith('-'):
            sign = -1
            s = s[1:]
        elif s.startswith('+'):
            sign = 1
            s = s[1:]
        else:
            sign = 1

        return sign * int(s, base)

